private static final Logger log = LoggerFactory.getLogger(OrderService.class);

public void processOrder(String orderId) {
    // Use parameterized logging to avoid unnecessary string concatenation
    log.debug("Processing order with ID: {}", orderId);

    try {
        executePayment();
    } catch (PaymentException e) {
        // Use ERROR for actionable issues, include the stack trace
        log.error("Payment failed for order: {}", orderId, e);
    }
}
